-- Minimal stand-ins for the Supabase pieces our migrations use, so the schema can be tested in a
-- plain Postgres container (scripts/test-db.sh). Never run this against a Supabase project.

create role anon nologin;
create role authenticated nologin;
create role service_role nologin bypassrls;

create schema extensions;
create schema auth;
create schema storage;

grant usage on schema public to anon, authenticated, service_role;
grant usage on schema auth to authenticated, service_role;

create table auth.users (
  id uuid primary key default gen_random_uuid(),
  email text,
  raw_user_meta_data jsonb not null default '{}',
  raw_app_meta_data jsonb not null default '{}'
);

-- A signed-in device: its refresh tokens go with it (the real tables have more columns).
create table auth.sessions (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users (id) on delete cascade);
create table auth.refresh_tokens (id bigserial primary key, session_id uuid references auth.sessions (id) on delete cascade, user_id text, token text);

-- Auth's OAuth server (an AI assistant's connection), with the columns our functions read, as
-- supabase/gotrue v2.197 has them: the apps that registered, who approved which (until revoked), and
-- the app a sign-in belongs to.
create table auth.oauth_clients (id uuid primary key default gen_random_uuid(), client_name text, logo_uri text, redirect_uris text, deleted_at timestamptz);
create table auth.oauth_consents (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users (id) on delete cascade,
  client_id uuid not null references auth.oauth_clients (id) on delete cascade,
  scopes text not null default '',
  granted_at timestamptz not null default now(),
  revoked_at timestamptz,
  unique (user_id, client_id)
);
alter table auth.sessions add column oauth_client_id uuid references auth.oauth_clients (id) on delete cascade;

-- Same contract as Supabase's auth.uid(): the "sub" claim of the request's JWT.
create function auth.uid() returns uuid language sql stable as $$
  select coalesce(
    nullif(current_setting('request.jwt.claim.sub', true), ''),
    nullif(current_setting('request.jwt.claims', true), '')::jsonb ->> 'sub'
  )::uuid
$$;
grant execute on function auth.uid() to anon, authenticated, service_role;

-- Same contract as Supabase's auth.role(): the "role" claim of the request's JWT.
create function auth.role() returns text language sql stable as $$
  select coalesce(
    nullif(current_setting('request.jwt.claim.role', true), ''),
    nullif(current_setting('request.jwt.claims', true), '')::jsonb ->> 'role'
  )
$$;
grant execute on function auth.role() to anon, authenticated, service_role;

create table storage.buckets (id text primary key, name text not null, public boolean not null default false);
create table storage.objects (
  id uuid primary key default gen_random_uuid(),
  bucket_id text references storage.buckets (id),
  name text not null,
  owner uuid,
  metadata jsonb, -- Storage fills it in once the file is stored: mimetype, size and so on
  created_at timestamptz default now()
);
-- Storage's own index for finding a folder's files (storage limits look a company's up with it).
create index idx_objects_bucket_id_name on storage.objects (bucket_id, name collate "C");
alter table storage.objects enable row level security;
grant usage on schema storage to authenticated, service_role;
grant select, insert, update, delete on storage.objects to authenticated;

create publication supabase_realtime;

-- Planet Ops: signing a quote, proposal or change order as the customer does, for the database tests
-- (20261120000100_planet_ops_change_order_signature.sql): a drawing from the app's own signature pad
-- (apps/api/test/fixtures/signaturePad.ts PAD_SHORT, a short two-stroke signature), the version
-- fingerprint of the page it was signed from, written as the server writes it. Tests only.
create schema planet_test;
grant usage on schema planet_test to anon, authenticated, service_role;
create function planet_test.drawn() returns text language sql immutable as $sig$ select 'data:image/png;base64,'::text $sig$;
-- Signs it as the customer (a draft too, as in person) and returns its id; one already signed or
-- accepted is left as it is. Runs as the server (no one signed in), as the API signs.
create function planet_test.sign(p_quote uuid, p_name text default 'Test Customer') returns uuid
language plpgsql security definer as $fn$
declare v_claims text := current_setting('request.jwt.claims', true);
begin
  perform set_config('request.jwt.claims', '{"role": "service_role"}', true);
  update public.quotes
     set status = 'approved', approved_at = now(),
         approval = jsonb_build_object('name', p_name, 'signed_at', now(), 'signature', planet_test.drawn(),
                                       'seen_fingerprint', private.quote_fingerprint(id))
                    || jsonb_build_object('subtotal', subtotal, 'discount_amount', discount_amount, 'tax_amount', tax_amount, 'total', total)
   where id = p_quote and status in ('draft', 'sent', 'changes_requested');
  perform set_config('request.jwt.claims', coalesce(v_claims, ''), true);
  return p_quote;
end $fn$;
grant execute on all functions in schema planet_test to anon, authenticated, service_role;
-- The approval the client hub sends for a customer signing on their link: what the test gives (the
-- printed name, the add-ons...), with the drawing, a signing time and the fingerprint of the page.
create function planet_test.approval(p_quote uuid, p_given jsonb default '{}') returns jsonb
language plpgsql stable security definer as $fn$
begin
  return jsonb_build_object('name', 'Test Customer', 'signed_at', now()) || coalesce(p_given, '{}')
      || jsonb_build_object('signature', planet_test.drawn(), 'seen_fingerprint', private.quote_fingerprint(p_quote));
end $fn$;
grant execute on function planet_test.approval(uuid, jsonb) to anon, authenticated, service_role;
